// แปลง MISP restSearch response -> รูปแบบเดียวกับ Mock CTI Feed { source, title, link, published, content }
// สำคัญ: backend /intel/ingest สกัด IoC/CVE/T-code/facts จาก field `content` เอง (regex ฝั่ง server)
// จึงต้อง "แบน" attribute + galaxy(ATT&CK) + tag ของ MISP event ลงเป็นข้อความใน content ให้ regex เดิมจับได้
const MISP_BASE_URL = 'https://localhost'; // ใช้สร้าง link ให้คนเปิดจาก browser บน host (node Fetch เรียก MISP ผ่าน https://host.docker.internal เพราะอยู่คนละ docker network) ห้ามมี / ปิดท้าย
const events = $input.first().json.response ?? [];

// [Option A] จัดอันดับ event ตามความเกี่ยวข้องกับ AD แล้วเลือกเฉพาะ TOP_N ตัวแรก
// อ้างเกณฑ์คะแนนจากเอกสาร ad-attack-surface-attack-v19.md:
//   ★★★ AD-specific (ไม่มีความหมายถ้าไม่มี AD) -> weight 100
//   ★★  สำคัญสูงบน Domain Controller           -> weight 10
//   ★   พบบ่อยในเส้นทางโจมตี AD                  -> weight 1
// score ของ event = ผลรวม weight ของ T-code ไม่ซ้ำที่พบใน event (technique ที่ไม่อยู่ในเอกสาร = 0)
// เรียง score มาก->น้อย (tiebreak: published ใหม่สุดก่อน) แล้วตัดเอา TOP_N
// ตั้ง TOP_N <= 0 = ไม่จำกัด (gen ทุก event = พฤติกรรมแบบ B)
const TOP_N = 3;

const STAR3 = ['T1078.002','T1098','T1098.007','T1136.002','T1556','T1556.001','T1556.002','T1556.005','T1556.007','T1068','T1134.005','T1484','T1484.001','T1484.002','T1003','T1003.003','T1003.006','T1110.003','T1187','T1552.006','T1557','T1557.001','T1558','T1558.001','T1558.002','T1558.003','T1558.004','T1606.002','T1649','T1069','T1069.002','T1087','T1087.002','T1482','T1615','T1021','T1021.002','T1550.002','T1550.003','T1006','T1036.010','T1207','T1222','T1222.001','T1685.001','T1685.005','T1486','T1489','T1490','T1531','T1071.004'];
const STAR2 = ['T1588.002','T1588.006','T1078.001','T1078.003','T1133','T1199','T1047','T1053.005','T1059.001','T1569.002','T1037.001','T1037.003','T1098.005','T1112','T1543.003','T1546.003','T1547.002','T1547.003','T1547.005','T1547.008','T1556.006','T1556.008','T1556.009','T1134','T1134.001','T1134.002','T1134.003','T1003.001','T1003.004','T1003.005','T1040','T1110','T1110.001','T1110.002','T1552','T1552.001','T1552.002','T1552.004','T1555','T1555.004','T1018','T1033','T1046','T1135','T1201','T1021.001','T1021.003','T1021.006','T1072','T1210','T1550','T1563.002','T1570','T1014','T1036','T1036.004','T1036.005','T1070','T1070.003','T1070.004','T1070.006','T1070.009','T1564.002','T1553','T1553.002','T1553.004','T1553.006','T1685','T1685.003','T1686','T1686.003','T1687','T1688','T1689','T1005','T1039','T1074.001','T1119','T1560','T1090','T1105','T1219','T1572','T1041','T1048','T1567','T1485','T1499','T1561.001','T1561.002','T1565.001'];
const STAR1 = ['T1589.001','T1589.002','T1589.003','T1590','T1591','T1595.002','T1587.003','T1588.004','T1190','T1566','T1059.003','T1059.005','T1127.001','T1574.001','T1505.005','T1547.001','T1055','T1548.002','T1003.002','T1056.001','T1110.004','T1111','T1528','T1558.005','T1621','T1016','T1049','T1652','T1534','T1027','T1202','T1211','T1216','T1218.005','T1218.011','T1218.014','T1497','T1071.001','T1205','T1030','T1600','T1690'];
const TECH_WEIGHT = {};
for (const t of STAR3) TECH_WEIGHT[t] = 100;
for (const t of STAR2) TECH_WEIGHT[t] = 10;
for (const t of STAR1) TECH_WEIGHT[t] = 1;

// [ข้อ 1] map คำใน tag/title/comment -> T-code (กรณี MISP event ไม่มี Galaxy)
// เก็บเฉพาะ mapping ที่มั่นใจสูง — อย่าเดา เพราะ technique ผิดทำให้ playbook ป้องกันผิดจุด
const KEYWORD_TO_TCODE = [
  ['dll side loading', 'T1574.002'], ['dll side-loading', 'T1574.002'], ['dll sideloading', 'T1574.002'],
  ['byovd', 'T1068'], ['bring your own vulnerable driver', 'T1068'],
  ['password spraying', 'T1110.003'], ['brute force', 'T1110'],
  ['credential dumping', 'T1003'], ['lsass', 'T1003.001'], ['mimikatz', 'T1003.001'],
  ['kerberoast', 'T1558.003'], ['pass-the-hash', 'T1550.002'], ['pass the hash', 'T1550.002'],
  ['spearphishing', 'T1566.001'], ['spear phishing', 'T1566.001'], ['phishing', 'T1566'],
  ['process injection', 'T1055'], ['scheduled task', 'T1053.005'], ['powershell', 'T1059.001'],
  ['ransomware', 'T1486'],
];
function mapKeywordsToTcodes(text) {
  const low = (text || '').toLowerCase();
  const hits = new Set();
  for (const [kw, tcode] of KEYWORD_TO_TCODE) { if (low.includes(kw)) hits.add(tcode); }
  return [...hits];
}

const scored = [];
for (const wrap of events) {
  const ev = wrap.Event ?? wrap;

  // รวม attribute ทั้งที่แขวนกับ event ตรง ๆ และที่อยู่ใน MISP Object
  const attrs = [...(ev.Attribute ?? [])];
  for (const obj of (ev.Object ?? [])) attrs.push(...(obj.Attribute ?? []));

  const lines = [];
  if (ev.info) lines.push(ev.info);

  // IoC: ใส่ค่าดิบลงตรง ๆ ให้ regex backend จับ (ip-src/ip-dst, domain/hostname, md5/sha1/sha256, vulnerability=CVE)
  for (const a of attrs) {
    if (['link', 'comment', 'text', 'other', 'attachment'].includes(a.type)) continue;
    const note = a.comment ? ` (${a.comment})` : '';
    lines.push(`${a.category}/${a.type}: ${a.value}${note}`);
  }

  // MITRE ATT&CK galaxy -> external_id = T-code (backend สกัดด้วย \bT\d{4}(\.\d{3})?\b)
  for (const g of (ev.Galaxy ?? [])) {
    for (const cl of (g.GalaxyCluster ?? [])) {
      const ext = Array.isArray(cl.meta?.external_id)
        ? cl.meta.external_id.join(' ')
        : (cl.meta?.external_id ?? '');
      lines.push(`ATT&CK: ${cl.value ?? ''} ${ext}`.trim());
    }
  }

  // Tag ระดับ event (เผื่อ T-code/CVE ถูกแปะเป็น tag แทน galaxy)
  for (const t of (ev.Tag ?? [])) lines.push(`Tag: ${t.name}`);

  // [ข้อ 1] กู้ technique จากคำใน tag/title/comment เมื่อ event ไม่มี Galaxy
  const kwText = [ev.info, ...(ev.Tag ?? []).map(t => t.name), ...attrs.map(a => a.comment)].join(' ');
  const mapped = mapKeywordsToTcodes(kwText);
  if (mapped.length) lines.push('ATT&CK (keyword-mapped): ' + mapped.join(' '));

  const content = lines.join('\n');

  // [Option A] คิดคะแนนความเกี่ยวข้อง AD จาก T-code ไม่ซ้ำใน content (ใช้ regex เดียวกับ backend)
  const tcodes = [...new Set(content.match(/\bT\d{4}(?:\.\d{3})?\b/g) || [])];
  let score = 0;
  for (const tc of tcodes) score += (TECH_WEIGHT[tc] ?? 0);

  const publishedMs = ev.publish_timestamp
    ? Number(ev.publish_timestamp) * 1000
    : (ev.date ? Date.parse(`${ev.date}T00:00:00Z`) : 0);
  const publishedIso = publishedMs ? new Date(publishedMs).toISOString() : null;

  scored.push({
    score,
    publishedMs: publishedMs || 0,
    json: {
      source: `MISP — สกมช/NCSA${ev.Orgc?.name ? ' (' + ev.Orgc.name + ')' : ''}`,
      title: ev.info || `MISP Event ${ev.id}`,
      link: `${MISP_BASE_URL}/events/view/${ev.id}`,
      published: publishedIso,
      content,
      misp_event_id: ev.id,
      misp_uuid: ev.uuid,
    }
  });
}

// เรียงตามคะแนน (มาก->น้อย) แล้ว published ใหม่สุดก่อนเมื่อคะแนนเท่ากัน
scored.sort((a, b) => (b.score - a.score) || (b.publishedMs - a.publishedMs));

// ตัดเอา TOP_N ตัวแรก (TOP_N <= 0 = ไม่จำกัด)
// event ที่ไม่ถูกเลือกยังไม่ถูก mark-processed จึงมีสิทธิ์ถูกหยิบในรอบถัดไป — ไม่หลุดถาวร
const selected = TOP_N > 0 ? scored.slice(0, TOP_N) : scored;

// ไม่มี event เข้าเกณฑ์ -> คืน array ว่าง ให้ flow จบเงียบ ๆ ไม่สร้าง playbook เปล่า
return selected.map(s => ({ json: s.json }));

// Mock CTI feed — 2 เรื่องคนละภัย (dedup_key ต่างกัน) เพื่อทดสอบว่า Loop Over Items สร้าง playbook 2 ตัว
// เรื่อง 1: AD brute-force (CVE-2025-21298) · เรื่อง 2: credential dumping/Kerberoasting (CVE-2025-29812)
// ทั้งคู่ status=created → เข้า loop → ได้ playbook คนละใบ
return [
  { json: {
      source: 'The Hacker News',
      title: 'New Brute-Force Campaign Targets Active Directory via RDP and Password Spraying',
      link: 'https://thehackernews.com/2026/08/ad-bruteforce-campaign.html',
      published: '2026-08-21T02:10:00Z',
      content: "Researchers have uncovered a large-scale campaign targeting enterprise Active Directory environments. The attackers perform password spraying (T1110.003) and password guessing (T1110.001) against domain accounts, then move laterally over RDP (T1021.001). Attack traffic originates from 45.155.205[.]233 and 185.220.101[.]45, and tooling is hosted at hxxp://ad-brute-tools[.]top/payload.exe (SHA256: e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855). The campaign abuses weak password policies, and organizations lagging on CVE-2025-21298 patching face elevated risk. Administrators are urged to enforce account lockout policies and monitor failed logon events."
  }},
  { json: {
      source: 'CISA',
      title: 'Credential Dumping and Kerberoasting Campaign Targets Domain Service Accounts',
      link: 'https://www.cisa.gov/news-events/alerts/2026/08/22/cred-dumping-kerberoast',
      published: '2026-08-22T06:00:00Z',
      content: "A newly observed intrusion set is targeting enterprise Active Directory to harvest credentials. After gaining a foothold, the actors dump credentials from LSASS memory (T1003.001) using a custom tool, then perform Kerberoasting (T1558.003) to crack service account hashes and move laterally via pass-the-hash (T1550.002). Command-and-control traffic was observed to 193.42.33[.]14 and 45.9.148[.]200, with a loader retrieved from hxxp://kerb-dump-tools[.]top/loader.bin (SHA256: 9f2b7c1d4e6a8b0c9f2b7c1d4e6a8b0c9f2b7c1d4e6a8b0c9f2b7c1d4e6a8b0c). The actors leverage CVE-2025-29812 for privilege escalation. Defenders should enable LSASS protection (RunAsPPL), restrict and monitor service account privileges, and alert on anomalous Kerberos TGS requests."
  }}
];

// ประกอบ prompt เชิงรุก: fill_instruction + facts จากข่าว (verbatim) + IoCs + RAG chunks
const intel = $('Loop Over Items').first().json.intel;
const sec = $('Split Out Sections').item.json;
const rag = $json;

const chunks = (rag.chunks ?? []).map((c, i) => `[${i + 1}] (${c.source_doc})\n${c.text}`).join('\n---\n');
const missing = rag.missing_techniques ?? [];

const factsBlock = (intel.facts ?? []).map((f, i) => `(${i + 1}) ${f}`).join('\n');
const iocLines = [
  ...(intel.iocs.ips ?? []).map(v => `IP: ${v}`),
  ...(intel.iocs.domains ?? []).map(v => `Domain: ${v}`),
  ...(intel.iocs.hashes ?? []).map(v => `Hash: ${v}`),
  ...(intel.iocs.cves ?? []).map(v => `CVE: ${v}`)
].join('\n');

const intelContext = [
  `Threat report: ${intel.threat_name}`,
  `Source: ${intel.feed_name} (${intel.link ?? '-'})`,
  `Techniques: ${intel.mitre_techniques.join(', ')}`
].join('\n');

const missingBlock = missing.length
  ? `\n⚠️ ไม่มีข้อมูลใน knowledge base รองรับ technique: ${missing.join(', ')}\nให้แปะธง ⚠️ ในแถวที่เกี่ยวข้อง และห้ามแต่งขั้นตอนขึ้นเอง`
  : '';

const prompt = `คุณเป็น SOC analyst ที่เขียนแผนป้องกันเชิงรุก (Proactive Defense Playbook) จากข่าวกรองภัยคุกคาม
สำคัญ: องค์กรยังไม่ถูกโจมตี — นี่คือการเตรียมป้องกันล่วงหน้า ไม่ใช่การตอบสนองเหตุการณ์ที่เกิดแล้ว

${sec.fill_instruction}

--- THREAT INTELLIGENCE ---
${intelContext}

--- FACTS จากข่าว (คัดตรงจากต้นฉบับ) ---
${factsBlock || '(ไม่มี)'}

--- IoCs ---
${iocLines || '(ไม่มี)'}

--- KNOWLEDGE BASE (ใช้เฉพาะข้อมูลด้านล่างนี้เท่านั้น ห้ามเพิ่มจากความรู้ตัวเอง) ---
${chunks || '(ไม่พบข้อมูลรองรับ)'}
${missingBlock}

เขียนที่ระดับแนวทาง/วิธีการ (procedure) ไม่ผูกกับ OS ใด OS หนึ่ง ยกคำสั่งเป็นตัวอย่างสั้นๆ ได้แต่ห้ามให้คำสั่งเป็นแกนหลักของขั้นตอน

ตอบเป็นตาราง Markdown เท่านั้น ไม่ต้องมีคำนำหรือคำสรุป`;

return { json: { phase: sec.phase, heading: sec.heading, prompt } };

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
const meta = $('Build Prompt').item.json;

return {
  json: {
    phase: meta.phase,
    heading: meta.heading,
    content: text.trim()
  }
};

// ยุบ 3 items กลับเป็น 1 ก้อน (ฝั่งเชิงรุก — ไม่มี NCSC/CTI enrichment, ใช้ intel + IoC table แทน)
const intel = $('Loop Over Items').first().json.intel;
const sections = $input.all().map(i => i.json);

const allRag = $('Retrieve Chunks').all().map(i => i.json);
const missing = [...new Set(allRag.flatMap(r => r.missing_techniques ?? []))];

return [{
  json: {
    intel_id: intel.intel_id,
    threat_name: intel.threat_name,
    technique_ids: intel.mitre_techniques,
    severity: 'advisory (proactive)',
    alert: {},
    sections,
    missing_techniques: missing,
    playbook_type: 'proactive',
    intel_source: {
      feed: intel.feed_name,
      title: intel.title,
      link: intel.link,
      published: intel.published
    },
    iocs: intel.iocs
  }
}];

// ก้อนสุดท้าย — สองข้อความพร้อมส่ง แยก field ให้ต่อ Teams/LINE node ในอนาคตได้ทันที
return [{
  json: {
    playbook_id: $('Save Draft').first().json.playbook_id,
    intel_id: $('Aggregate Sections').first().json.intel_id,
    executive_message: $json.executive_message,
    it_message: $json.it_message
  }
}];

// [ข้อ 2] เอา technique ที่ VT กู้จาก hash มาทับ intel.mitre_techniques แล้วส่งต่อรูปเดิม {status, intel, ...}
// ⭐ ย้ายออกมา "นอก Loop" แล้ว: รันครั้งเดียวกับทุก event — จับคู่ผล VT (Enrich Hashes) กับ intel เดิม
//    (Filter New Intel) ด้วย index เพราะ Enrich Hashes เป็น http ที่รักษาลำดับ 1:1 ต่อ item
// ทำ "ก่อน" Split by Technique เพื่อให้ technique ที่ VT เพิ่งกู้มาได้แตกเป็น playbook ของตัวเองด้วย
const bases = $('Filter New Intel').all();
const enriched = $input.all();
return enriched.map((e, i) => {
  const base = bases[i].json;
  const enrich = e.json;
  const intel = { ...base.intel, mitre_techniques: enrich.technique_ids ?? base.intel.mitre_techniques };
  intel.vt_enrichment = {
    added: enrich.added_techniques ?? [],
    live_calls: enrich.live_calls ?? 0,
    rate_limited: enrich.rate_limited ?? false,
    per_hash: enrich.per_hash ?? [],
  };
  return { json: { ...base, intel } };
});

// ⭐ 1 technique = 1 playbook (ตามที่อาจารย์กำหนด): แตก 1 event -> N items (item ละ 1 technique)
// ทำ "หลัง" Apply Enrichment เพื่อให้รวม technique ที่ VT กู้จาก hash เข้ามาแตกเป็นใบของมันเองด้วย
// node ปลายน้ำใน Loop (Retrieve/Build Prompt/Aggregate) อ่าน intel.mitre_techniques = [technique เดียว]
// จึง retrieve+prompt+assemble เจาะจงต่อ technique -> ได้ playbook แยกใบ (dedup_key ต่างกันต่อ technique)
const out = [];
for (const it of $input.all()) {
  const base = it.json;
  const intel = base.intel;
  const techs = [...new Set(intel.mitre_techniques ?? [])];
  // event ไม่มี technique เลย -> ข้าม (สร้าง playbook เชิงป้องกันเจาะจง technique ไม่ได้)
  // ยังไม่ mark-processed จึงมีสิทธิ์ถูกหยิบรอบหน้าถ้าภายหลังมี technique เพิ่ม
  techs.forEach((t, i) => {
    out.push({
      json: {
        ...base,
        technique_id: t,
        tech_index: i,
        tech_total: techs.length,
        intel: { ...intel, mitre_techniques: [t] },
      },
    });
  });
}
return out;
